import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.DA0HUBZR.js";const k=JSON.parse('{"title":"09 · 用 AI 生成接口用例","description":"","frontmatter":{"title":"09 · 用 AI 生成接口用例"},"headers":[],"relativePath":"chapters/ch09.md","filePath":"chapters/ch09.md","lastUpdated":1794815418000}'),n={name:"chapters/ch09.md"};function l(d,t,r,p,o,h){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-9-章-·-用-ai-生成接口用例-以及为什么不能全信" tabindex="-1">第 9 章 · 用 AI 生成接口用例（以及为什么不能全信） <a class="header-anchor" href="#第-9-章-·-用-ai-生成接口用例-以及为什么不能全信" aria-label="Permalink to &quot;第 9 章 · 用 AI 生成接口用例（以及为什么不能全信）&quot;">​</a></h1><p>AI 能在几分钟内产出一百条用例，也能在几分钟内产出一百条<strong>看起来对、其实跑不了</strong>的用例。差别不在模型，在你喂进去的东西和接出来的流程。</p><p>这一章讲三件事：怎么把接口文档变成用例矩阵、怎么写出能用的提示词、生成之后怎么审。</p><h2 id="_1-先把文档变成矩阵-再让-ai-填" tabindex="-1">1. 先把文档变成矩阵，再让 AI 填 <a class="header-anchor" href="#_1-先把文档变成矩阵-再让-ai-填" aria-label="Permalink to &quot;1. 先把文档变成矩阵，再让 AI 填&quot;">​</a></h2><p>不要一上来就让模型「给这个接口写 30 条用例」。先自己列维度，模型只负责在每个格子里填内容：</p><table tabindex="0"><thead><tr><th>维度</th><th>取值</th></tr></thead><tbody><tr><td>参数</td><td>必填缺失、类型错、超长、越界、非法枚举、多余字段</td></tr><tr><td>位置</td><td>query / path / body / header 放错</td></tr><tr><td>鉴权</td><td>无 token、过期 token、他人资源、低权限</td></tr><tr><td>业务状态</td><td>初始态、进行中、终态、非法流转</td></tr><tr><td>幂等/并发</td><td>重复提交、同 key、并发两次</td></tr><tr><td>数据量</td><td>0 条、1 条、边界条数、超上限</td></tr><tr><td>兼容</td><td>新增字段、字段改名、空值语义</td></tr></tbody></table><p>一个接口 7 个维度、每维 2–3 个取值，就是 15–20 条用例，<strong>覆盖是设计出来的，不是模型想出来的</strong>。</p><h2 id="_2-提示词的四段结构" tabindex="-1">2. 提示词的四段结构 <a class="header-anchor" href="#_2-提示词的四段结构" aria-label="Permalink to &quot;2. 提示词的四段结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【角色】你是接口测试工程师，服务端是 FastAPI + SQLite。</span></span>
<span class="line"><span>【输入】以下是接口契约（OpenAPI 片段）+ 业务规则（3 条）。</span></span>
<span class="line"><span>【任务】按给定的维度矩阵，为每个接口生成用例；每个格子至少 1 条。</span></span>
<span class="line"><span>【输出】严格输出 JSON 数组，字段固定：id/title/priority/type/precondition/steps/request/expected/asserts。</span></span>
<span class="line"><span>   约束：expected 必须可判定（状态码 + 字段 + 值），禁止出现「正常返回」这类描述。</span></span></code></pre></div><p>四个要点：</p><ol><li><strong>给契约，不给截图</strong>。OpenAPI / JSON Schema 比「接口文档截图」准确得多。</li><li><strong>给维度，不给形容词</strong>。「覆盖全面」没有信息量，「必填缺失 / 类型错 / 越界各一条」才有。</li><li><strong>给输出 schema</strong>。字段固定，后面才能自动化校验。</li><li><strong>给硬约束</strong>。<code>expected</code> 必须可判定，这条能过滤掉大半废话。</li></ol><h2 id="_3-生成之后必须过的五道审" tabindex="-1">3. 生成之后必须过的五道审 <a class="header-anchor" href="#_3-生成之后必须过的五道审" aria-label="Permalink to &quot;3. 生成之后必须过的五道审&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查</th><th>不通过的典型样子</th><th>处理</th></tr></thead><tbody><tr><td>可执行</td><td>「验证系统稳定运行」</td><td>删或改写</td></tr><tr><td>可判定</td><td>「返回正确的数据」</td><td>补状态码与字段断言</td></tr><tr><td>不重复</td><td>同一维度 8 条，另一维度 0 条</td><td>按矩阵补缺口</td></tr><tr><td>前置清楚</td><td>没说要不要登录、用哪个账号</td><td>补 precondition</td></tr><tr><td>数据可造</td><td>要求一个不存在的「已退款订单」</td><td>标依赖，交给数据准备</td></tr></tbody></table><p>审完再进用例库。<strong>AI 负责产量，人负责覆盖与判定</strong>——这条分工不能反。</p><h2 id="_4-用覆盖矩阵验收「生成得好不好」" tabindex="-1">4. 用覆盖矩阵验收「生成得好不好」 <a class="header-anchor" href="#_4-用覆盖矩阵验收「生成得好不好」" aria-label="Permalink to &quot;4. 用覆盖矩阵验收「生成得好不好」&quot;">​</a></h2><p>生成 30 条不代表覆盖 7 个维度。跑一遍矩阵统计：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接口              参数  位置  鉴权  状态  幂等  数据量  兼容</span></span>
<span class="line"><span>POST /api/users    5     1     3     2     2     3      0   ← 兼容维度是空的</span></span>
<span class="line"><span>GET  /api/users    4     1     2     0     0     3      1</span></span></code></pre></div><p>空格子就是下一轮的输入。这个矩阵可以脚本化（本章实验就做了一个）。</p><h2 id="_5-ai-在接口测试里真正擅长的四件事" tabindex="-1">5. AI 在接口测试里真正擅长的四件事 <a class="header-anchor" href="#_5-ai-在接口测试里真正擅长的四件事" aria-label="Permalink to &quot;5. AI 在接口测试里真正擅长的四件事&quot;">​</a></h2><ol><li><strong>从文档抄成用例骨架</strong>：把 OpenAPI 的字段约束翻译成边界值。</li><li><strong>补异常分支</strong>：人容易漏 409/422/429 这类错误码。</li><li><strong>写断言</strong>：把「返回正确」翻译成「<code>status==201</code> 且 <code>id</code> 是正整数且 <code>Location</code> 匹配 <code>/api/users/\\d+</code>」。</li><li><strong>解释失败</strong>：把响应体和请求体一起给它，让它判断是断言写错还是服务端错（第 14 章做）。</li></ol><p>不擅长的：判断业务规则对不对、决定优先级、知道哪些用例值得自动化。</p><h2 id="_6-本章实操" tabindex="-1">6. 本章实操 <a class="header-anchor" href="#_6-本章实操" aria-label="Permalink to &quot;6. 本章实操&quot;">​</a></h2><p><code>labs/ch09-ai-cases/</code>：</p><ul><li><code>spec.py</code>：一份手写的接口契约（三个接口，带字段约束），模拟 OpenAPI 的子集；</li><li><code>matrix.py</code>：按维度矩阵生成用例，输出覆盖统计；</li><li><code>prompt.py</code>：把契约 + 矩阵拼成提示词（含 JSON schema 与硬约束）；</li><li><code>review.py</code>：对「模型产出的用例」做五道审，输出可执行/需修改/丢弃三档。</li></ul><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> labs\\ch09</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ai</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cases\\run_demo.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest labs\\ch09</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ai</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cases </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q</span></span></code></pre></div><p>实验里不调用真实模型：<code>review.py</code> 审的是一份<strong>故意写坏的样例</strong>（含「返回正确」「验证稳定性」这类），你能直观看到五道审怎么把它们筛掉。</p><h2 id="_7-自测" tabindex="-1">7. 自测 <a class="header-anchor" href="#_7-自测" aria-label="Permalink to &quot;7. 自测&quot;">​</a></h2><ol><li>为什么先列维度再让 AI 填，比直接让 AI「写 30 条」更好？</li><li>你的提示词里如果漏了输出 schema，会在哪一步付出代价？</li><li>「期望结果必须可判定」这条约束，能过滤掉哪三类用例？</li><li>覆盖矩阵里某一格是 0，你应该补用例还是删维度？判断依据是什么？</li><li>举一个「AI 生成得很对，但你不该自动化」的用例。</li></ol><h2 id="附-自测答案" tabindex="-1">附：自测答案 <a class="header-anchor" href="#附-自测答案" aria-label="Permalink to &quot;附：自测答案&quot;">​</a></h2><ol><li>维度先定等于先划好搜索空间：每个格子都必须有交代，缺了能看见；直接让 AI「写 30 条」它会在容易的地方堆量、难的地方跳过，你拿到一堆重复用例还没法判断覆盖率。</li><li>会在「解析结果」这一步付出代价：字段名漂移、结构化失败、要写一堆兜底和重试，最后还是要人工整理，等于白让 AI 干一遍。</li><li>过滤三类：不可判定的（「功能正常」「返回正确」）、不可执行的（缺前置数据、依赖人工确认）、重复的（同一接口同一维度同一场景）。</li><li>先判断这一格对该接口是否适用：比如「文件上传」维度对纯 JSON 接口就不适用，标注 N/A 即可；适用却为 0，就必须补用例。</li><li>例子：一次性运营活动的报名接口——数据不可重复造、名额有限、牵涉真实业务资源；或涉及真实支付扣款、不可回滚的场景。这类适合人工验证 + 监控，不适合进自动化。</li></ol><h2 id="学生常问" tabindex="-1">学生常问 <a class="header-anchor" href="#学生常问" aria-label="Permalink to &quot;学生常问&quot;">​</a></h2><p><strong>Q：AI 生成的用例能直接用吗？</strong></p><p>A：不能。它是草稿，必须过五道审：可执行、可判定、不重复、前置清楚、数据可造。审完通常要删掉三分之一、改写三分之一，剩下的才是能进仓库的。</p><p><strong>Q：提示词要写多长？</strong></p><p>A：够用就行，但四段不能少：角色、输入（接口定义/字段/规则）、任务（按维度补哪些格子）、输出（JSON schema + 硬约束）。约束越具体，返工越少。</p><p><strong>Q：怎么让 AI 生成的期望结果可判定？</strong></p><p>A：要求它写「状态码 + 关键字段 + 字段值或格式」，例如「返回 201，body.id 为非空整数，body.name 等于入参 name」。禁止出现「正常」「成功」这类词。</p><h2 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h2><p><strong>Q：你怎么评估一组接口用例的覆盖度？</strong></p><p>A：接口 × 维度矩阵：行是接口，列是参数/位置/鉴权/状态/幂等/数据量/兼容，逐格填数量，空格即为缺口；再叠加业务链路（跨接口的场景）和异常路径的比例。覆盖率不追求 100%，但每个高风险接口的关键维度不能为空。</p><p><strong>Q：AI 生成用例的准确率怎么量化？</strong></p><p>A：用一批人工标好的样本做基准：生成 N 条，统计「可直接采纳 / 需修改 / 丢弃」的比例，再看漏报（人工有而 AI 没有的）。只看生成数量没有意义。</p><p><strong>Q：用例设计里「等价类 + 边界值」为什么仍然重要？</strong></p><p>A：它们决定了抽样是否合理。AI 容易在中间值上堆用例，边界（0、1、最大值、超一位、空串）才是 bug 高发区，这一层必须人工把关。</p><h2 id="延伸知识" tabindex="-1">延伸知识 <a class="header-anchor" href="#延伸知识" aria-label="Permalink to &quot;延伸知识&quot;">​</a></h2><ul><li>覆盖矩阵要跟着接口变化更新，否则半年后没人知道哪些格子是「没测」还是「不需要测」。</li><li>用例的「前置」写不清楚，自动化就一定不稳；前置里出现「先手动登录」的，等于还没设计完。</li><li>期望结果里避免写死自增 id 和时间戳，用范围、格式或相对断言。</li><li>把「不该自动化的用例」明确列出来（一次性活动、真实支付、需要人工判断的视觉验收），比硬塞进 CI 更专业。</li></ul>`,46)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
